interface ToolExecutionContext {
  conversationId: string;
  messageId: string;
  wasApproved?: boolean;
  approvedAt?: number;
  deniedAt?: number;
}

interface ToolResult {
  success: boolean;
  output?: unknown;
  error?: string;
  duration?: number;
}

interface ToolExecutionLog {
  id: string;
  conversationId: string;
  messageId: string;
  toolName: string;
  args: unknown;
  result?: ToolResult;
  status: 'pending' | 'executed' | 'error';
  approved?: boolean;
  timestamp: number;
  duration?: number;
}

code_state.schema_definition:

// Epic 24: Performance & UX Optimization tables
toolExecutionLogs!: Table<ToolExecutionLogRecord, string>;

this.version(11).stores({
  toolExecutionLogs: 'id, conversationId, messageId, toolName, timestamp'
});

// ToolExecutionLogRecord type
interface ToolExecutionLogRecord {
  id: string;
  conversationId: string;
  messageId: string;
  toolName: string;
  args: Record<string, unknown>;
  result?: {
    success: boolean;
    output?: unknown;
    error?: string;
  };
  status: 'pending' | 'executed' | 'error' | 'denied';
  approved?: boolean;
  timestamp: number;
  duration?: number;
}

code_state.helper_functions:

async function addToolExecutionLog(log: ToolExecutionLogRecord): Promise<void> {
  await db.toolExecutionLogs.add(log);
}

async function updateToolExecutionLog(
  id: string,
  updates: Partial<ToolExecutionLogRecord>
): Promise<void> {
  await db.toolExecutionLogs.update(id, updates);
}

async function getToolExecutionLogs(
  conversationId: string
): Promise<ToolExecutionLogRecord[]> {
  return db.toolExecutionLogs
    .where('conversationId')
    .equals(conversationId)
    .sortBy('timestamp');
}

async function clearToolExecutionLogs(conversationId?: string): Promise<void> {
  if (conversationId) {
    await db.toolExecutionLogs
      .where('conversationId')
      .equals(conversationId)
      .delete();
  } else {
    await db.toolExecutionLogs.clear();
  }
}

code_state.current_implementation:

export class AgentFileTools {
  constructor(private webcontainer: WebContainer) {}

  async readFile(context: ToolExecutionContext, params: { path: string }) {
    // Current: No logging
    const entries = await this.webcontainer.fs.readFile(params.path, 'utf-8');
    return entries;
  }

  async writeFile(context: ToolExecutionContext, params: { path: string; content: string }) {
    // Current: No logging
    await this.webcontainer.fs.writeFile(params.path, params.content);
    return { success: true };
  }

  async listFiles(context: ToolExecutionContext, params: { path: string }) {
    // Current: No logging
    const entries = await this.webcontainer.fs.readdir(params.path);
    return entries;
  }
}
